using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class StringKeyedMembersGenerationTests
{
    [Fact]
    public async Task StringKeyedFieldAndPropertyAreBothInGeneratedFormatter()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [MessagePackObject]
                public class MyObject
                {
                    [Key("k1")]
                    public int ReceiptDistinctFieldName;

                    [Key("k2")]
                    public int ReceiptDistinctPropertyName { get; set; }
                }
            }
            """;
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> allRefs = frameworkRefs.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsGenAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            allRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGenerators(compilation);
        GeneratorDriverRunResult result = driver.GetRunResult();

        string generated = string.Join("\n", result.GeneratedTrees.Select(t => t.GetText().ToString()));
        Assert.False(string.IsNullOrEmpty(generated));
        Assert.Contains("ReceiptDistinctPropertyName", generated);
        Assert.Contains("ReceiptDistinctFieldName", generated);
    }
}
